from pathlib import Path
import base64, gzip, json

payload = ''
files = json.loads(gzip.decompress(base64.b64decode(payload)).decode())
for name, content in files.items():
    path = Path(name)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")

viewport_path = Path("apps/web/src/viewport/GlobalThreeViewport.ts")
source = viewport_path.read_text(encoding="utf-8")
def replace_once(old: str, new: str) -> None:
    global source
    if old not in source:
        raise SystemExit(f"GlobalThreeViewport patch marker not found: {old[:100]!r}")
    source = source.replace(old, new, 1)

