styles_path = Path("apps/web/src/styles.css")
styles = styles_path.read_text(encoding="utf-8")
style_append = '\n\n/* Prompt 10 XPBD Worker controls */\n.simulation-toolbar {\n  position: absolute;\n  z-index: 8;\n  left: max(10px, env(safe-area-inset-left));\n  bottom: max(42px, calc(env(safe-area-inset-bottom) + 10px));\n  display: grid;\n  gap: 6px;\n  max-width: min(360px, calc(100% - 20px));\n  padding: 8px;\n  border: 1px solid rgb(255 255 255 / 18%);\n  border-radius: 10px;\n  background: rgb(18 20 24 / 78%);\n  color: #fff;\n  backdrop-filter: blur(10px);\n  pointer-events: auto;\n}\n\n.simulation-toolbar[hidden] {\n  display: none;\n}\n\n.simulation-status-label {\n  font-size: 0.72rem;\n  line-height: 1.3;\n}\n\n.simulation-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n\n.simulation-actions button {\n  min-width: 44px;\n  min-height: 36px;\n  padding: 6px 10px;\n  border: 1px solid rgb(255 255 255 / 24%);\n  border-radius: 8px;\n  background: rgb(255 255 255 / 12%);\n  color: inherit;\n  font: inherit;\n  cursor: pointer;\n}\n\n.simulation-actions button:disabled {\n  cursor: not-allowed;\n  opacity: 0.5;\n}\n\n@media (max-width: 760px) {\n  .simulation-toolbar {\n    right: max(10px, env(safe-area-inset-right));\n    max-width: none;\n  }\n\n  .simulation-actions button {\n    min-height: 44px;\n    flex: 1 1 0;\n  }\n}\n'
if "/* Prompt 10 XPBD Worker controls */" not in styles:
    styles_path.write_text(styles + style_append, encoding="utf-8")

plan_path = Path("docs/PHYSICS_PLAN.md")
plan = plan_path.read_text(encoding="utf-8") if plan_path.exists() else "# Plano de física\n"
plan_append = '\n\n## Implementação do Prompt 10\n\nO núcleo XPBD CPU está implementado em Worker real com passo semi-fixo, buffers SoA tipados, restrições de warp/weft/shear/bend, costuras interpoladas, anchors, rollback estável e pool triplo de `ArrayBuffer`. O viewport atualiza `BufferGeometry` in-place e não usa React no loop por partícula. Colisões corporais, atrito e espessuras de contato permanecem deliberadamente no Prompt 11.\n'
if "## Implementação do Prompt 10" not in plan:
    plan_path.write_text(plan + plan_append, encoding="utf-8")
